design.css:
/* Pocket: izumi for Steam Deck-class handhelds. Pad first, touch second, legible at arm's length. */

/* Top bar: section tabs as pills between the L1/R1 glyphs; the page you are on is filled. */
[data-slot="nav.top"] { background: #0d1015 !important; border-color: #1f2530 !important; }
[data-slot="nav.top"] [data-part="nav.item"] { height: 36px; padding: 0 11px; border-radius: 999px; color: #a0a8b6; font-size: 15px; font-weight: 600; }
[data-slot="nav.top"] [data-part="nav.item"]:hover { background: #1e232c; color: #f2f4f7; }
[data-slot="nav.top"] [data-part="nav.item"][data-active] { background: #3daeff; color: #0a1220; }
[data-part="nav.bumper"] { margin: 0 2px; }

/* Glyphs and the hint bar. */
[data-part="hints.glyph"] { background: #e8ecf2; color: #0d1015; }
[data-slot="hints"] { background: #0d1015; border-color: #1f2530; font-size: 15px; }
[data-part="hints.label"] { color: #dfe4ec; }

/* Rows: 20 px headings; "View more" always visible (no hover on touch or pad). */
[data-part="row.title"] { font-size: 20px; font-weight: 700; letter-spacing: -0.01em; }
[data-part="row.more"] { opacity: 1 !important; color: #3daeff; font-size: 14px; }
[data-part="row.caption.title"] { font-size: 16px; color: #f2f4f7; }
[data-part="row.caption.meta"] { font-size: 14px; color: #a0a8b6; }

/* Cards: one-line 15 px titles and 14 px meta, never smaller. */
[data-part="card.title"] { font-size: 15px; font-weight: 600; line-height: 1.3; -webkit-line-clamp: 1; }
[data-part="card.meta"] { font-size: 14px; }
[data-part="card.episode"] { font-size: 14px; }

/* Never below 14 px where a page gives a hook (Valve's 9 px panel minimum at the Deck's 1.25× zoom);
   uppercase badges at 13 px keep a 9 px cap height. */
[data-part="card.badge"] { font-size: 13px; }
[data-part="episode.number"] { font-size: 16px; }
[data-part="episode.meta"], [data-part="person.role"], [data-part="detail.meta"], [data-part="detail.airing"], [data-part="chip"] { font-size: 14px; }

/* Series page and tabs. */
[data-part="tab"] { font-size: 16px; }
[data-part="tab"][data-active] { background: #3daeff; color: #0a1220; }
[data-slot="nav.drawer"] [data-part="nav.item"] { min-height: 48px; font-size: 16px; }
[data-slot="nav.drawer"] [data-part="nav.item"][data-active] { background: #1e232c; color: #3daeff; }

/* Pad focus: an accent ring with a soft glow on artwork and tabs. Paint only (no transform
   transitions), so it can't trip WebKitGTK's layer-drop blink. */
:scope.gamemode [data-part="card"] a:focus [data-part="card.art"],
:scope.gamemode [data-part="card"]:focus [data-part="card.art"],
:scope.controller-mode [data-part="card"] a:focus [data-part="card.art"],
:scope.controller-mode [data-part="card"]:focus [data-part="card.art"] { box-shadow: 0 0 0 3px #3daeff, 0 0 22px rgba(61, 174, 255, 0.4); }
:scope.gamemode [data-part="tab"]:focus, :scope.controller-mode [data-part="tab"]:focus,
:scope.gamemode [data-part="episode"]:focus, :scope.controller-mode [data-part="episode"]:focus { box-shadow: 0 0 0 3px #3daeff; }
